{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer kernen: varig funktionsnedsættelse, journaler, udrednings- og behandlingsforløb, aktuelle symptomer. Men der er væsentlige fejl og mangler. Det udlægger vejledningens obligatoriske oplysninger som noget, dokumentationen kun 'bør' beskrive. Det henviser til L 152-forarbejderne som 'forslag' og ikke gældende hjemmel, selvom bekendtgørelsen og vejledningen er gældende. Det nævner ikke erhvervsevne og ikke 'hvis tilgængeligt i journalen'. Det siger heller ikke eksplicit, at diagnosen medtages, hvis den er stillet."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker varig funktionsnedsættelse, udrednings- og behandlingsforløb og aktuelle symptomer/hverdagspåvirkning. Det mangler flere kritiske elementer: påvirkning af erhvervsevnen (hvis muligt), diagnose hvis stillet som positivt element, planlagt behandling som krav, og at oplysningerne skal fremsendes når de er tilgængelige i journalen. Kravet om aktualitet nævnes kun gennem forarbejderne og slutkonklusionen."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive. Afsnittet om forarbejderne er sidespor, men erstatter ikke svaret."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: vejledning nr. 10157, SU-bekendtgørelsen og L 152 (2024-25). Påstandene er knyttet til dem via nummererede henvisninger og en kildeliste."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledningen og SU-bekendtgørelsen er gyldige og autoritative. L 152-forarbejderne er et lovforslag fra 2025, der ikke er en del af den frosne gældende kildeafgrænsning, og svaret erkender selv, at de ikke er gældende hjemmel. Det bruges alligevel til substantielle påstande om, hvad der ikke er nok. De er derfor ikke en anvendelig kilde."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke fuldt ud af de angivne passager. Påstanden om, at diagnose alene eller medicinkort ikke er tilstrækkeligt, bygger på forarbejderne og ikke på vejledningen. Den 'praktiske tommelfingerregel' og påstanden om, at dokumentationen skal vise funktionsevne 'i din hverdag', er knyttet til kilde 3 og 7, men de fremhævede passager er kun vejledningens minimumskrav og udgangspunktet om varighed. Betegnelsen 'bør' og 'helst' afspejler ikke vejledningens 'skal'."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at diagnose alene eller medicinkort ikke er tilstrækkeligt, med støtte i et lovforslag uden for den frosne kildeafgrænsning. Det tilføjer også en uunderbygget tommelfingerregel om, at dokumentationen bør 'helst' vise bestemte ting."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke de krævede forbehold: 'hvis diagnose er stillet', 'hvis behandling er planlagt', 'hvis erhvervsevnen kan beskrives' og at oplysningerne skal fremsendes, når de er tilgængelige i journalen eller anden eksisterende lægefaglig dokumentation. Erhvervsevne og planlagt behandling er ikke nævnt med forbeholdene."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt uens. Det siger først, at dokumentationen 'skal' beskrive visse ting, derefter at den kun 'bør' det. Det afviser forarbejderne som ikke gældende hjemmel, men bruger dem alligevel til en central påstand. Konklusionen er desuden formuleret som 'mest nærliggende', hvilket ikke følger klart af de angivne trin."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Vejledningens 'skal' om aktuel og fyldestgørende dokumentation og om, at oplysninger skal fremsendes, gengives som 'bør' og 'helst'. Det svækker en pligt til en blød anbefaling. 'Udgangspunkt' i § 37, stk. 2 er til gengæld gengivet nogenlunde, selvom bestemmelsen har en udtrykkelig undtagelse, som ikke er nævnt."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "no",
      "reason": "Svaret nævner kun 'ren diagnose' som utilstrækkelig. Det siger ikke, at diagnosen skal oplyses, hvis der er stillet en."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret nævner udrednings- og behandlingsforløb og et forløb i konklusionen, og dækker dermed i hovedsagen sygdomsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Svaret nævner udrednings- og behandlingsforløb eksplicit."
    },
    "A45": {
      "label": "partial",
      "reason": "Svaret nævner 'eventuelt er planlagt' behandling i tommelfingerreglen. Det er kun som en blød anbefaling og med uklar kildestøtte, og forbeholdet er til stede i svagere form."
    },
    "A47": {
      "label": "no",
      "reason": "Svaret nævner ikke påvirkning af erhvervsevnen."
    }
  },
  "overall_notes": "Svaret rammer minimumskravet om journaler og beskrivelse af varig funktionsnedsættelse samt forløb og aktuelle symptomer, og kilder er angivet. Det mangler erhvervsevne, diagnose-hvis-stillet og tilgængelighedsforbeholdet, svækker 'skal' til 'bør', og støtter sig på et lovforslag uden for den gældende kildeafgrænsning."
}

